// IngredientFilter provides filtering for Ingredient queries
type IngredientFilter struct {
	Id           *UUIDFilter
	StepKey      *UUIDFilter
	Quantity     *StringFilter
	Substitutes  *StringFilter
	EntityKey    *UUIDFilter
	DeletedOnRef *BoolFilter
	Version      *Int64Filter
	// RecipeID allows filtering by foreign key
	RecipeID *UUIDFilter
	// RefID allows filtering by foreign key
	RefID *UUIDFilter
	// Recipe keeps the rows whose recipe is a Recipe row the
	// filter finds (D90): one condition, the foreign key in the keys of the
	// Recipe rows it finds.
	Recipe *RecipeFilter
	// Ref keeps the rows whose ref is a live RecipeRef row the
	// filter finds (D90): one condition, the foreign key in the keys of the
	// RecipeRef rows it finds.
	Ref *RecipeRefFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []IngredientFilter
}

// IngredientUpdate provides fields that can be updated
type IngredientUpdate struct {
	StepKey      *types.IdentityUUID
	Quantity     *string
	Substitutes  *types.GenericJSON
	EntityKey    *types.IdentityUUID
	DeletedOnRef *bool
	// RecipeID allows updating the foreign key for recipe
	RecipeID *types.IdentityUUID
	// RefID allows updating the foreign key for ref
	RefID *types.IdentityUUID
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewIngredientSnapshotUpdate maps every mutable field from a complete
// Ingredient value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewIngredientSnapshotUpdate(input *types.Ingredient) *IngredientUpdate {
	update := &IngredientUpdate{}
	if input == nil {
		return update
	}
	update.StepKey = &input.StepKey
	update.Quantity = &input.Quantity
	update.Substitutes = &input.Substitutes
	update.EntityKey = input.EntityKey
	update.DeletedOnRef = &input.DeletedOnRef
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *IngredientUpdate) ApplyTo(row *types.Ingredient) {
	if u == nil || row == nil {
		return
	}
	if u.StepKey != nil {
		row.StepKey = *u.StepKey
	}
	if u.Quantity != nil {
		row.Quantity = *u.Quantity
	}
	if u.Substitutes != nil {
		row.Substitutes = *u.Substitutes
	}
	if u.EntityKey != nil {
		row.EntityKey = u.EntityKey
	}
	if u.DeletedOnRef != nil {
		row.DeletedOnRef = *u.DeletedOnRef
	}
	if u.RecipeID != nil {
		row.Recipe.Id = u.RecipeID
	}
	if u.RefID != nil {
		row.Ref.Id = u.RefID
	}
}

// IngredientFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND. A nil filter has none.
func IngredientFilterConditions(filter *IngredientFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a IngredientFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *IngredientFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

