// NewRecipeCommitSnapshotUpdate maps every mutable field from a complete
// RecipeCommit value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewRecipeCommitSnapshotUpdate(input *types.RecipeCommit) *RecipeCommitUpdate {
	update := &RecipeCommitUpdate{}
	if input == nil {
		return update
	}
	var zeroMessage string
	if input.Message == zeroMessage {
		update.MessageSetNull = true
	} else {
		update.Message = &input.Message
	}
	update.SchemaEpoch = &input.SchemaEpoch
	update.ContentHash = &input.ContentHash
	if input.Sequence == nil {
		update.SequenceSetNull = true
	} else {
		update.Sequence = input.Sequence
	}
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *RecipeCommitUpdate) ApplyTo(row *types.RecipeCommit) {
	if u == nil || row == nil {
		return
	}
	if u.MessageSetNull {
		var zeroMessage string
		row.Message = zeroMessage
	} else if u.Message != nil {
		row.Message = *u.Message
	}
	if u.SchemaEpoch != nil {
		row.SchemaEpoch = *u.SchemaEpoch
	}
	if u.ContentHash != nil {
		row.ContentHash = *u.ContentHash
	}
	if u.SequenceSetNull {
		row.Sequence = nil
	} else if u.Sequence != nil {
		row.Sequence = u.Sequence
	}
	if u.RootID != nil {
		row.Root.Id = u.RootID
	}
	if u.RefID != nil {
		row.Ref.Id = u.RefID
	}
	if u.ParentCommitIDSetNull {
		row.ParentCommit = nil
	} else if u.ParentCommitID != nil {
		if row.ParentCommit == nil {
			row.ParentCommit = &types.RecipeCommit{}
		}
		row.ParentCommit.Id = u.ParentCommitID
	}
}

// RecipeCommitFilterConditions are the filter's conditions for a query of
